      SUBROUTINE DBEAMSCC     CALCULATES PARTIAL DERIVATIVES OF THE INITIAL BEAM MATRIXC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM1B.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'SVP.CIN'CC     LOCAL VARIABLESC      INTEGER          J, JU, K      REAL             EPSC, SIGGC-------------------------------------------------------------------------------C      SIGG = DPARM      NV2 = IABS(NV2)      IF (NORD3 .LT. 1) GO TO 100      IF (.NOT. SVP(NV2)) THEN        DO 110 J = 1, 6        COV(J,NV2) = 0.0        DO 110 K = 1, 6        SV(J,K,NV2) = 0.0  110   CONTINUE      ENDIFC      IF (ACCEL .OR. LTWISS) THEN        IF ((ACCEL .AND. (JV .EQ. 1 .OR. JV .EQ. 3))     1     .OR. JV .EQ. 10 .OR. JV .EQ. 13) THEN          IF (JV .EQ. 1 .OR. JV .EQ. 10) THEN            JU = 1            EPSC = EPSX          ELSE            JU = 3            EPSC = EPSY          ENDIF          SV(JU,JU,NV2) = SIGG*EPSC*UBEAM(JU)/UBEAM(JU+1)          SV(JU+1,JU+1,NV2) = - SIGG*EPSC*SI(JU+1,JU+1)*UBEAM(JU)/     1                        (SI(JU,JU)*UBEAM(JU+1))        ELSE IF ((ACCEL .AND. (JV .EQ. 2 .OR. JV .EQ. 4))     1   .OR. JV .EQ. 11 .OR. JV .EQ. 14) THEN          IF (JV .EQ. 2 .OR. JV .EQ. 11) THEN            JU = 2            EPSC = EPSX          ELSE            JU = 4            EPSC = EPSY          ENDIF          SV(JU-1,JU,NV2) = - SIGG*EPSC          SV(JU,JU-1,NV2) = - SIGG*EPSC          SV(JU,JU,NV2) = - 2.0*SIGG*EPSC*SI(JU-1,JU)/SI(JU-1,JU-1)        ENDIF      ELSE        SV(JV,JV,NV2) = SV(JV,JV,NV2)     1                + 2.0*SIGG*SQRT(SI(JV,JV))*UBEAM(JV)      ENDIF      SVP(NV2) = .TRUE.  100 RETURN      END